=== FILE: lifo4_fcov.sv ===
// lifo4_fcov: functional coverage model for the lifo4 stack block.
// Planned from the approved requirement matrix (traceability_matrix.md, plan-audit).
//
// CLOSURE STATEMENT
// Sampling: every rising edge of clk, using the port values just before the edge.
// count is the stack occupancy before the edge.
// Occupancy classes: empty = count==0, mid = count 1..3, full = count==4.
// Operation classes (counted only with rst_n high):
//   push alone = push & ~pop, pop alone = pop & ~push, both = push & pop.
//
// Planned bins (15):
//   0  PUSH alone, empty      LIFO-PUSH
//   1  PUSH alone, mid        LIFO-PUSH
//   2  PUSH alone, full       LIFO-OVERFLOW
//   3  POP  alone, empty      LIFO-UNDERFLOW
//   4  POP  alone, mid        LIFO-POP
//   5  POP  alone, full       LIFO-POP
//   6  BOTH, empty            LIFO-BOTH-EMPTY
//   7  BOTH, mid              LIFO-REPLACE
//   8  BOTH, full             LIFO-REPLACE
//   9  occupancy 0            (all)
//   10 occupancy 1            (all)
//   11 occupancy 2            (all)
//   12 occupancy 3            (all)
//   13 occupancy 4            (all)
//   14 reset (rst_n low) while count != 0   LIFO-RESET
//
// Exclusions: none. The matrix names no unreachable scenario and waives none.
// Hit bits are sticky: reset of the block never clears coverage.
/* verilator lint_off UNUSEDSIGNAL */
module lifo4_fcov (
    input  logic       clk, rst_n, push, pop,
    input  logic [7:0] din, dout,
    input  logic [2:0] count,
    input  logic       empty, full, err,
    output int         planned,   // how many bins the model plans
    output int         holes      // how many of them have not been hit yet
);
/* verilator lint_on UNUSEDSIGNAL */

    localparam int NBINS = 15;

    logic [NBINS-1:0] hit;

    initial hit = '0;

    logic occ_empty, occ_mid, occ_full;
    logic op_push, op_pop, op_both;

    assign occ_empty = (count == 3'd0);
    assign occ_mid   = (count >= 3'd1) && (count <= 3'd3);
    assign occ_full  = (count == 3'd4);

    assign op_push = push && !pop;
    assign op_pop  = pop && !push;
    assign op_both = push && pop;

    always_ff @(posedge clk) begin
        if (rst_n) begin
            if (op_push && occ_empty) hit[0]  <= 1'b1;
            if (op_push && occ_mid)   hit[1]  <= 1'b1;
            if (op_push && occ_full)  hit[2]  <= 1'b1;
            if (op_pop  && occ_empty) hit[3]  <= 1'b1;
            if (op_pop  && occ_mid)   hit[4]  <= 1'b1;
            if (op_pop  && occ_full)  hit[5]  <= 1'b1;
            if (op_both && occ_empty) hit[6]  <= 1'b1;
            if (op_both && occ_mid)   hit[7]  <= 1'b1;
            if (op_both && occ_full)  hit[8]  <= 1'b1;
            if (count == 3'd0)        hit[9]  <= 1'b1;
            if (count == 3'd1)        hit[10] <= 1'b1;
            if (count == 3'd2)        hit[11] <= 1'b1;
            if (count == 3'd3)        hit[12] <= 1'b1;
            if (count == 3'd4)        hit[13] <= 1'b1;
        end else begin
            if (count != 3'd0)        hit[14] <= 1'b1;
        end
    end

    assign planned = NBINS;
    assign holes   = NBINS - $countones(hit);

endmodule
=== END FILE ===
